(()=>{'use strict';
const d=window.B13EffectsData;if(!d){document.getElementById('scene-status').textContent='播放資料未載入。請重新解壓完整網站資料夾。';throw new Error('B13EffectsData unavailable')}
const audio=document.getElementById('narration-audio'),stage=document.getElementById('effects-stage'),img=document.getElementById('scene-image'),nextImg=document.getElementById('scene-next-image'),canvas=document.getElementById('visual-effect'),ctx=canvas.getContext('2d'),quote=document.getElementById('poem-quote'),caption=document.getElementById('subtitle-text'),title=document.getElementById('chapter-title'),seek=document.getElementById('seek-slider'),status=document.getElementById('scene-status'),rafState={id:0},reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;let currentId='',nextId='',chapterActive=-1,activeScene=-1;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),ease=v=>{v=clamp(v,0,1);return v*v*(3-2*v)};
const format=t=>{t=Math.max(0,Math.floor(t));return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`};
function at(ms){let lo=0,hi=d.scenes.length-1;while(lo<=hi){const m=(lo+hi)>>1,s=d.scenes[m];if(ms<s.startMs)hi=m-1;else if(ms>=s.endMs)lo=m+1;else return m}return Math.max(0,Math.min(d.scenes.length-1,hi))}
function chapterAt(ms){for(let i=0;i<d.chapters.length;i++){const c=d.chapters[i];if(ms>=c.startMs&&ms<c.endMs)return i}return Math.max(0,d.chapters.length-1)}
function motion(s,ms){const u=clamp((ms-s.startMs)/Math.max(1,s.endMs-s.startMs),0,1),r=ease(u);let scale=s.motion==='push'?1+r*.05:s.motion==='pull'?1.05-r*.05:s.motion==='settle'?1.02+r*.02:1.045;let x=s.motion==='pan-left'?1.25-r*2.5:s.motion==='pan-right'?-1.25+r*2.5:s.motion==='diagonal'?.8*(-1+r*2):0;let y=s.motion==='diagonal'?.6-r*1.2:0;return `scale(${scale}) translate(${x}%,${y}%)`}
function drawFx(effect,ms,op,w,h){if(!effect||op<=0)return;const r=effect.region,u=clamp((ms-effect.startMs)/Math.max(1,effect.endMs-effect.startMs),0,1),phase=reduced()?0:u*Math.PI*2,x=w*r.x/100,y=h*r.y/100,rw=w*r.w/100,rh=h*r.h/100;ctx.save();ctx.beginPath();ctx.rect(0,h*.18,w,h*.62);ctx.clip();ctx.beginPath();ctx.rect(x,y,rw,rh);ctx.clip();ctx.globalAlpha=.055*op;const rgb=effect.mode==='warm'||effect.mode==='paper'?'255,224,151':'199,226,255';
if(effect.mode==='mist'){for(let i=0;i<3;i++){const cx=x+rw*(.22+i*.31)+Math.sin(phase*.7+i)*rw*.045,cy=y+rh*(.35+i%2*.25),g=ctx.createRadialGradient(cx,cy,1,cx,cy,rw*.32);g.addColorStop(0,`rgba(${rgb},.42)`);g.addColorStop(1,`rgba(${rgb},0)`);ctx.fillStyle=g;ctx.fillRect(x,y,rw,rh)}}
else if(effect.mode==='ripple'){for(let i=0;i<3;i++){const p=reduced()?.45:(u*1.4+i/3)%1;ctx.beginPath();ctx.ellipse(x+rw*(.35+(i%2)*.3),y+rh*.58,rw*(.08+p*.19),rh*(.025+p*.12),0,0,Math.PI*2);ctx.strokeStyle=`rgba(${rgb},${.35*(1-p)})`;ctx.lineWidth=Math.max(1,w*.0012);ctx.stroke()}}
else if(effect.mode==='leaf'){for(let i=0;i<6;i++){const cx=x+rw*((i*.173+.08)%1),cy=y+rh*((i*.29+.2)%1),sz=Math.max(3,w*.006);ctx.save();ctx.translate(cx,cy);ctx.rotate(Math.sin(phase+i)*.18);ctx.fillStyle=`rgba(188,215,164,${.42*op})`;ctx.beginPath();ctx.ellipse(0,0,sz*1.8,sz*.65,0,0,Math.PI*2);ctx.fill();ctx.restore()}}
else if(effect.mode==='paper'||effect.mode==='beam'){const cx=x+rw*(reduced()?.5:(.15+.7*((u+.15)%1))),g=ctx.createLinearGradient(cx-rw*.13,0,cx+rw*.13,0);g.addColorStop(0,'rgba(255,237,183,0)');g.addColorStop(.5,'rgba(255,237,183,.58)');g.addColorStop(1,'rgba(255,237,183,0)');ctx.fillStyle=g;ctx.fillRect(x,y,rw,rh)}
else if(effect.mode==='warm'){const cx=x+rw*(.35+.3*(u%1)),cy=y+rh*.5,g=ctx.createRadialGradient(cx,cy,1,cx,cy,rw*.42);g.addColorStop(0,`rgba(255,220,147,${reduced()?.5:.35+.25*Math.sin(phase)})`);g.addColorStop(1,'rgba(255,220,147,0)');ctx.fillStyle=g;ctx.fillRect(x,y,rw,rh)}
else{for(let i=0;i<8;i++){const p=reduced()?.5:(u+i/8)%1,cx=x+rw*((i*.137+.12)%1),cy=y+rh*((i*.317+.21)%1);ctx.globalAlpha=.08*op*(reduced()?.5:.35+.65*Math.sin(p*Math.PI));ctx.fillStyle=`rgba(${rgb},1)`;ctx.beginPath();ctx.arc(cx,cy,Math.max(1,w*.0015)*(1+2*p),0,Math.PI*2);ctx.fill()}}ctx.restore()}
function setImage(node,id){if(id===node.dataset.scene)return;node.dataset.scene=id;node.src=`./assets/images/${id}.webp`}
function updateQuote(ms,scene,w,h){const q=d.quotes.find(v=>ms>=v.startMs&&ms<v.endMs&&v.imageId===scene.workbookId);if(!q){quote.hidden=true;quote.classList.remove('is-visible');quote.textContent='';return}quote.hidden=false;quote.classList.add('is-visible');quote.textContent=q.text;quote.setAttribute('aria-label',`${q.author}《${q.work}》：${q.text}`);quote.style.left=q.box.x+'%';quote.style.top=q.box.y+'%';quote.style.width=q.box.w+'%';quote.style.height=q.box.h+'%';quote.style.fontSize=Math.max(12,Math.min(w*.041,(q.box.w/100*w)/Math.max(5,Math.min(8,[...q.text].length/2)),(q.box.h/100*h)/2.45))+'px'}
function draw(){rafState.id=0;const ms=audio.currentTime*1000,i=at(ms),s=d.scenes[i],effect=d.effects[i],w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;const dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);if(i!==activeScene){activeScene=i;currentId=s.workbookId;setImage(img,currentId);img.style.opacity='1';nextImg.style.opacity='0';nextId=''}img.style.transform=motion(s,ms);let oldOp=1;const n=d.scenes[i+1];if(n&&Math.abs(n.startMs-s.endMs)<2){const dur=(n.chapterId!==s.chapterId?900:650),begin=s.endMs-dur;if(ms>=begin&&ms<s.endMs){const p=ease((ms-begin)/dur);oldOp=1-p;setImage(nextImg,n.workbookId);nextImg.style.transform=motion(n,n.startMs);nextImg.style.opacity=String(p);drawFx(d.effects[i+1],ms,p,w,h)}else nextImg.style.opacity='0'}else nextImg.style.opacity='0';img.style.opacity=String(oldOp);drawFx(effect,ms,oldOp,w,h);const ci=chapterAt(ms),ch=d.chapters[ci];if(ci!==chapterActive){chapterActive=ci;title.textContent=ch.title;document.querySelectorAll('.chapter-list button').forEach((b,j)=>b.classList.toggle('active',j===ci))}const sub=d.subtitles.find(v=>ms>=v.startMs&&ms<v.endMs);caption.textContent=sub?.text||'';updateQuote(ms,s,w,h);document.getElementById('current-time').textContent=format(audio.currentTime);document.getElementById('duration-time').textContent='/ '+format(d.durationMs/1000);if(!seek.matches(':active'))seek.value=String(audio.currentTime);document.getElementById('scene-status').textContent=`第 ${i+1} / ${d.scenes.length} 鏡　｜　${ch.title}`;document.getElementById('play-control').textContent=audio.paused?'播放':'暫停';if(!audio.paused&&!audio.ended)rafState.id=requestAnimationFrame(draw)}
function requestDraw(){if(!rafState.id)rafState.id=requestAnimationFrame(draw)}
function go(ms){audio.currentTime=clamp(ms/1000,0,d.durationMs/1000);requestDraw()}
function button(label,action,extra=''){const b=document.createElement('button');b.type='button';b.innerHTML=label;b.addEventListener('click',action);if(extra)b.className=extra;return b}
function init(){
 const chapters=document.getElementById('chapter-list');
 d.chapters.forEach((c,i)=>{const b=button(`<span class="chapter-number">${String(i+1).padStart(2,'0')}</span><span class="chapter-name">${c.title}</span><small>${format(c.startMs/1000)}</small>`,()=>go(c.startMs),'chapter-button');chapters.append(b)});
 const play=document.getElementById('play-control'),mute=document.getElementById('mute-control'),volume=document.getElementById('volume-control'),subs=document.getElementById('subtitles-toggle');
 document.getElementById('restart-control').addEventListener('click',()=>{go(0);audio.play().catch(()=>{})});
 play.addEventListener('click',()=>audio.paused?audio.play().catch(()=>{}):audio.pause());
 seek.addEventListener('input',e=>{audio.currentTime=Number(e.target.value);requestDraw()});
 document.getElementById('previous-scene-control').addEventListener('click',()=>{const i=at(audio.currentTime*1000);go(d.scenes[Math.max(0,i-1)].startMs)});
 document.getElementById('next-scene-control').addEventListener('click',()=>{const i=at(audio.currentTime*1000);go(d.scenes[Math.min(d.scenes.length-1,i+1)].startMs)});
 document.getElementById('previous-chapter-control').addEventListener('click',()=>{const i=chapterAt(audio.currentTime*1000);go(d.chapters[Math.max(0,i-1)].startMs)});
 document.getElementById('next-chapter-control').addEventListener('click',()=>{const i=chapterAt(audio.currentTime*1000);go(d.chapters[Math.min(d.chapters.length-1,i+1)].startMs)});
 volume.addEventListener('input',()=>audio.volume=Number(volume.value));mute.addEventListener('click',()=>{audio.muted=!audio.muted;mute.textContent=audio.muted?'取消靜音':'靜音'});
 subs.addEventListener('change',()=>document.body.classList.toggle('subtitles-hidden',!subs.checked));
 seek.max=String(d.durationMs/1000);document.getElementById('duration-time').textContent='/ '+format(d.durationMs/1000);audio.volume=Number(volume.value);
 for(const ev of ['play','pause','timeupdate','seeking','seeked','loadedmetadata','ended'])audio.addEventListener(ev,()=>{play.innerHTML=audio.paused?'<span aria-hidden="true">▶</span> 播放':'暫停';requestDraw()});
 new ResizeObserver(requestDraw).observe(stage);requestDraw()
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

